CREATE TABLE el_course_packages(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,name TEXT NOT NULL,price INTEGER NOT NULL CHECK(typeof(price)='integer' AND price>0 AND price<=1000000000),currency TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),created_by TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,created_by) REFERENCES el_memberships(org_id,user_id));
CREATE INDEX el_course_packages_branch ON el_course_packages(org_id,branch_id,status,created_at);
CREATE TABLE el_course_package_items(org_id TEXT NOT NULL,package_id TEXT NOT NULL,course_id TEXT NOT NULL,PRIMARY KEY(package_id,course_id),FOREIGN KEY(org_id,package_id) REFERENCES el_course_packages(org_id,id),FOREIGN KEY(org_id,course_id) REFERENCES el_courses(org_id,id));
CREATE TABLE el_course_package_orders(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,package_id TEXT NOT NULL,student_id TEXT NOT NULL,invoice_id TEXT NOT NULL,summary_json TEXT NOT NULL,created_by TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(invoice_id),UNIQUE(package_id,student_id),FOREIGN KEY(org_id,package_id) REFERENCES el_course_packages(org_id,id),FOREIGN KEY(org_id,student_id) REFERENCES el_students(org_id,id),FOREIGN KEY(org_id,invoice_id) REFERENCES el_invoices(org_id,id),FOREIGN KEY(org_id,created_by) REFERENCES el_memberships(org_id,user_id));
CREATE TRIGGER el_course_package_item_guard BEFORE INSERT ON el_course_package_items BEGIN SELECT CASE WHEN (SELECT count(*) FROM el_course_package_items WHERE package_id=NEW.package_id)>=10 THEN RAISE(ABORT,'Course package item limit') END; SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_course_packages p JOIN el_course_branches b ON b.branch_id=p.branch_id AND b.org_id=p.org_id JOIN el_courses c ON c.id=b.course_id AND c.org_id=b.org_id WHERE p.id=NEW.package_id AND p.org_id=NEW.org_id AND c.id=NEW.course_id AND c.status='active') THEN RAISE(ABORT,'Course package course unavailable') END; END;
CREATE TRIGGER el_course_package_item_lock_update BEFORE UPDATE ON el_course_package_items BEGIN SELECT RAISE(ABORT,'Course package contents are immutable'); END;
CREATE TRIGGER el_course_package_item_lock_delete BEFORE DELETE ON el_course_package_items BEGIN SELECT RAISE(ABORT,'Course package contents are immutable'); END;
CREATE TRIGGER el_course_package_lock BEFORE UPDATE ON el_course_packages WHEN NEW.org_id<>OLD.org_id OR NEW.branch_id<>OLD.branch_id OR NEW.name<>OLD.name OR NEW.price<>OLD.price OR NEW.currency<>OLD.currency BEGIN SELECT RAISE(ABORT,'Course package terms are immutable'); END;
CREATE TRIGGER el_course_package_order_lock BEFORE UPDATE ON el_course_package_orders BEGIN SELECT RAISE(ABORT,'Course package order is immutable'); END;
CREATE TRIGGER el_course_package_order_delete BEFORE DELETE ON el_course_package_orders BEGIN SELECT RAISE(ABORT,'Course package order is immutable'); END;
CREATE TRIGGER el_course_package_order_guard BEFORE INSERT ON el_course_package_orders BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_course_packages p JOIN el_invoices i ON i.id=NEW.invoice_id AND i.org_id=p.org_id WHERE p.id=NEW.package_id AND p.org_id=NEW.org_id AND p.status='active' AND i.student_id=NEW.student_id AND i.branch_id=p.branch_id AND i.total=p.price AND i.currency=p.currency AND i.status='draft') THEN RAISE(ABORT,'Course package invoice mismatch') END; END;
CREATE TRIGGER el_course_package_cap BEFORE INSERT ON el_course_packages WHEN(SELECT count(*) FROM el_course_packages WHERE org_id=NEW.org_id)>=100 BEGIN SELECT RAISE(ABORT,'Course package definition limit'); END;
CREATE TRIGGER el_course_package_sold_items BEFORE INSERT ON el_course_package_items WHEN EXISTS(SELECT 1 FROM el_course_package_orders WHERE package_id=NEW.package_id) BEGIN SELECT RAISE(ABORT,'Course package contents are immutable'); END;
CREATE TRIGGER el_course_package_order_enrollments BEFORE INSERT ON el_course_package_orders BEGIN
 SELECT CASE WHEN (SELECT count(*) FROM el_course_package_items WHERE package_id=NEW.package_id)<2 OR EXISTS(SELECT 1 FROM el_course_package_items pi WHERE pi.package_id=NEW.package_id AND NOT EXISTS(SELECT 1 FROM el_enrollments en JOIN el_groups g ON g.id=en.group_id AND g.org_id=en.org_id JOIN json_each(NEW.summary_json,'$.groups') selected ON json_extract(selected.value,'$.id')=g.id JOIN el_course_packages p ON p.id=NEW.package_id WHERE en.student_id=NEW.student_id AND en.org_id=NEW.org_id AND en.status='active' AND g.course_id=pi.course_id AND g.branch_id=p.branch_id AND g.status='active')) THEN RAISE(ABORT,'Course package enrollments mismatch') END;
END;
